import{_ as h,o as y,a as f,c as i,b as e,F as l,r as d,i as b,E as v,g as w,h as o,f as _,w as x,t as s,l as k,e as g,n as p,j as L}from"./index-zn4-L2Tj.js";const E={class:"docs-page"},M={class:"docs-inner"},C={class:"sections-grid"},A={class:"section-card__num mono"},S={class:"section-card__title"},T={class:"section-card__desc"},D={key:0,class:"section-card__tags"},R={class:"quick-ref reveal"},O={class:"data-table"},N={class:"mono"},V={class:"mono"},P={__name:"DocsView",setup(F){let n;y(()=>{n=new IntersectionObserver(r=>r.forEach(a=>a.target.classList.toggle("visible",a.isIntersecting)),{threshold:.1}),setTimeout(()=>document.querySelectorAll(".docs-page .reveal").forEach(r=>n.observe(r)),100)}),f(()=>n==null?void 0:n.disconnect());const c=[{id:"overview",num:"01",title:"Project Overview",summary:"Can satellites tell us where backup generators are running during a blackout? The challenge: no public database of generators exists, so there are no ground-truth labels to train on. Our solution: hospitals, airports, and fire stations are legally required to have generators — so we use them as proxy labels. If satellite pixels near these facilities stay brighter during outages, the brightness pattern itself becomes a detectable signal. We test this across 25 major disasters in 17 U.S. states and Turkey (2016–2023).",tags:["VIIRS VNP46A2","25 Events","Proxy Labels"]},{id:"litreview",num:"02",title:"Literature Review",summary:"Previous research used nighttime lights to map where power went out during disasters. We invert the question: instead of detecting damage, we detect where lights stay on — a signal of backup power. Wang et al. (2018) pioneered satellite-based outage mapping; Zhang et al. (2023) extended it to damage assessment. Our contribution fills a gap: using the same data to find resilience rather than failure.",tags:["Wang 2018","Zhang 2023","Energy Equity"]},{id:"data",num:"03",title:"Data Collection & Processing",summary:'Since no generator registry exists, we build proxy labels from three open datasets: NASA Black Marble daily nighttime light images (500m resolution), DOE EAGLE-I power outage records, and OpenStreetMap critical facility locations. Pixels within 750m of a facility are labeled "near generator"; all others are the control group. This creates a panel of ~33,700 labeled pixels across 25 events — an imperfect but scalable alternative to ground-truth surveys. This section also covers cloud masking, Google Earth Engine workflows, and data quality challenges.',tags:["VNP46A2","EAGLE-I","OSM","Buffer Zones","Cloud QC"]},{id:"eda",num:"04",title:"Exploratory Data Analysis",summary:'Do pixels near proxy-labeled facilities actually behave differently during outages? We define the Resilience Ratio (R = NTL during outage / NTL before outage) and find that yes — but with complications. The "floor effect" means facilities in dimmer areas appear less resilient simply because they start darker. Facility type matters (hospitals vs. fire stations), and city size matters (Miami vs. Lake Charles). These patterns inform how we design the models.',tags:["Resilience Ratio","Floor Effect","Facility Groups","City Size"]},{id:"interpretive",num:"05",title:"Interpretive Modeling",summary:"We test whether the proxy labels carry a real signal using four statistical models (OLS, MixedLM, Logistic, Cox PH) — triangulation from different angles. Results: buffer pixels show +2.8% less NTL decline (p=0.020), 32% lower damage odds (OR=0.68), and 13% faster recovery (HR=1.13). However, land-use confounding partially explains the effect, and Leave-One-Event-Out cross-validation drops AUC from 0.73 to 0.45 — the statistical models don't generalize, motivating the predictive modeling phase.",tags:["OLS","MixedLM","Logistic","Cox PH","Triangulation","NLCD Confounding"]},{id:"features",num:"06",title:"Feature Engineering",summary:'We engineer 17 features to help models distinguish "generator running" from "just a bright area." The key challenge: our proxy labels are spatially biased — facilities cluster in certain urban zones. City-level normalization and interaction terms help separate the genuine generator brightness signal from the background urban brightness pattern.',tags:["17 features","Floor effect","Interactions"]},{id:"models",num:"07",title:"Predictive Models & Probability Maps",summary:"Can we predict which pixels have generators using only their nighttime light behavior — no location cheating? Four model variants answer this: Models A–C use spatial context (AUC ~0.967), but Model D uses only NTL temporal patterns (AUC 0.704). That 0.704 is the honest generator signal — real but modest at 500m resolution. The ensemble generates per-pixel backup power probability maps for all 25 events, validated against Miami-Dade generator permit records.",tags:["RF + XGB","LOEO","4 Model Variants","AUC 0.967"]},{id:"stage3",num:"08",title:"Zip-Code Analysis",summary:"Scaling up from pixels to policy: do zip codes with more critical facilities (our proxy for generator density) experience less severe outages? Spatial regression across 1,002 zip codes and 22 events using Model D probabilities (R² = 0.747 with Census controls). Closed-loop validation against EAGLE-I outage records is positive (β=+123.8, p=0.012) — backup detection lines up with where outages actually strike, the natural deployment direction. Equity gap: high-outage zip codes have only 63% of the facility density of low-outage areas. Miami-Dade permit ground-truth confirms only commercial-scale generators are detectable at 500m.",tags:["1,002 Zip Codes","Spatial Regression","OLS + SEM","Miami-Dade Validation"]},{id:"conclusions",num:"09",title:"Conclusions & Future Work",summary:"The proxy-label approach works at commercial scale. Model D (pure NTL, AUC 0.704) achieves above-baseline probability at 83% of Miami-Dade commercial generator permits but only 14% of residential — the 500m / 25-hectare pixel cleanly resolves institutional backup behavior but loses household units in the noise. Stage 3 closed-loop validation aligns with the natural deployment direction: places that suffer worse outages show higher detected probability. Future sensors at ≤100m (Luojia-1 class) could push detection down to residential.",tags:["Conclusions","Limitations","Future Work"]},{id:"web",num:"10",title:"Dashboard Development",summary:"This interactive dashboard is built with Vue 3 + Vite, featuring MapLibre GL JS for WebGL-accelerated map rendering with per-event probability heatmaps, canvas-rendered facility icons, and satellite/vector basemap switching. The site supports mobile responsive layouts, scroll-triggered animations, and is deployed via GitHub Actions to GitHub Pages.",tags:["Vue 3","Vite","MapLibre GL","GitHub Pages"]},{id:"repro",num:"11",title:"Reproducibility",summary:"All data sources are publicly available (NASA, OpenStreetMap, DOE), and the full analysis pipeline is implemented in Jupyter notebooks. This section provides the exact data product IDs, API endpoints, and key academic references needed to reproduce or extend the analysis.",tags:["GEE","Jupyter","Open data"]},{id:"references",num:"12",title:"References",summary:"Full bibliography of cited works including Wang et al. (2018) on NASA Black Marble outage monitoring, Zhang et al. (2023) on damage assessment, Román et al. (2018) on the Black Marble product suite, and literature on energy equity and infrastructure resilience.",tags:["Bibliography"]}];return(r,a)=>{const m=w("RouterLink");return o(),i("div",E,[e("div",M,[a[3]||(a[3]=e("div",{class:"page-header reveal"},[e("div",{class:"tag tag--cyan",style:{"margin-bottom":"10px"}},"Technical Documentation"),e("h1",{class:"page-header__title"},"Methodology & Data"),e("p",{class:"page-header__desc"},' Overview of the analysis pipeline — from satellite data acquisition to predictive modeling. Click "Read More" on any section for detailed technical documentation. ')],-1)),e("div",C,[(o(),i(l,null,d(c,t=>_(m,{key:t.id,to:`/docs/${t.id}`,class:"section-card reveal",style:p({transitionDelay:`${c.indexOf(t)*.06}s`})},{default:x(()=>[e("div",A,s(t.num),1),e("h3",S,s(t.title),1),e("p",T,s(t.summary),1),t.tags?(o(),i("div",D,[(o(!0),i(l,null,d(t.tags,u=>(o(),i("span",{key:u,class:"tag tag--dim"},s(u),1))),128))])):k("",!0),a[0]||(a[0]=e("div",{class:"section-card__cta"},[g(" Read More "),e("span",{class:"arrow"},"→")],-1))]),_:2},1032,["to","style"])),64))]),e("div",R,[a[2]||(a[2]=e("div",{class:"quick-ref__header"},[e("span",{class:"tag tag--amber"},"Quick Reference"),e("span",{style:{"font-size":"11px",color:"var(--text-muted)"}},"Study Events")],-1)),e("div",O,[e("table",null,[a[1]||(a[1]=e("thead",null,[e("tr",null,[e("th",null,"Event"),e("th",null,"Location"),e("th",null,"Year"),e("th",null,"Type"),e("th",null,"Affected")])],-1)),e("tbody",null,[(o(!0),i(l,null,d(b(v),t=>(o(),i("tr",{key:t.id},[e("td",null,[e("span",{class:"dot",style:p({background:t.color})},null,4),g(s(t.name),1)]),e("td",null,s(t.subtitle),1),e("td",N,s(t.year),1),e("td",null,[e("span",{class:L(["tag",`tag--${t.type}`]),style:{"font-size":"10px"}},s(t.type),3)]),e("td",V,s(t.affectedUsers),1)]))),128))])])])])])])}}},I=h(P,[["__scopeId","data-v-67eeddfb"]]);export{I as default};
